import { test } from "node:test";
import assert from "node:assert/strict";
import { parseToml } from "../src/toml.ts";
import { parseCargoLock, canonicalGitUrl } from "../src/cargo-lock.ts";
import { crateObjectKey, gitDbTarKey, gitDbListPrefix, gitIdent, indexEntryObjectKey, indexEntryDiskPath } from "../src/cargo-paths.ts";

const SAMPLE = `
# This file is automatically @generated by Cargo.
version = 3

[[package]]
name = "autocfg"
version = "1.1.0"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "d468802bab17cbc0cc575e9b053f41e72aa36bfa6b7f55e3529ffa43161b97fa"

[[package]]
name = "baml-core"
version = "0.1.0"
dependencies = [
 "autocfg",
 "serde",
]

[[package]]
name = "serde"
version = "1.0.197"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "3fb1c873e1b9b056a4dc4c0c198b24c3ffa059243875552b2bd0933b1aee4ce2"

[[package]]
name = "pest"
version = "2.7.0"
source = "git+https://github.com/pest-parser/pest?branch=master#abc123def456"

[[package]]
name = "weird"
version = "0.1.0"
source = "git+https://github.com/example/weird.git#deadbeef"
`;

test("toml: parses array-of-tables and top-level scalars", () => {
  const doc = parseToml(SAMPLE);
  assert.equal(doc.version, 3);
  assert.ok(Array.isArray(doc.package));
  assert.equal((doc.package as unknown[]).length, 5);
});

test("toml: strings, escapes, multiline, inline tables, arrays", () => {
  const doc = parseToml(`
title = "hello \\"world\\"\\n"
literal = 'C:\\path\\no\\escape'
multi = """
line1
line2"""
nums = [1, 2, 3]
nested = [
  "a",
  "b",
]
point = { x = 1, y = 2 }
hex = 0xFF
flag = true
neg = -17
flt = 3.14
`);
  assert.equal(doc.title, 'hello "world"\n');
  assert.equal(doc.literal, "C:\\path\\no\\escape");
  assert.equal(doc.multi, "line1\nline2");
  assert.deepEqual(doc.nums, [1, 2, 3]);
  assert.deepEqual(doc.nested, ["a", "b"]);
  assert.deepEqual(doc.point, { x: 1, y: 2 });
  assert.equal(doc.hex, 255);
  assert.equal(doc.flag, true);
  assert.equal(doc.neg, -17);
  assert.equal(doc.flt, 3.14);
});

test("toml: dotted keys and quoted keys", () => {
  const doc = parseToml(`
a.b.c = 1
"quoted key" = 2
[server]
"127.0.0.1" = "ok"
`);
  assert.deepEqual(doc.a, { b: { c: 1 } });
  assert.equal(doc["quoted key"], 2);
  assert.deepEqual(doc.server, { "127.0.0.1": "ok" });
});

test("cargo-lock: classifies registry vs git, skips path deps", () => {
  const lock = parseCargoLock(SAMPLE);
  assert.equal(lock.version, 3);
  assert.equal(lock.registry.length, 2);
  const names = lock.registry.map((p) => p.name).sort();
  assert.deepEqual(names, ["autocfg", "serde"]);
  const autocfg = lock.registry.find((p) => p.name === "autocfg")!;
  assert.equal(autocfg.crateFile, "autocfg-1.1.0.crate");
  assert.equal(
    autocfg.checksum,
    "d468802bab17cbc0cc575e9b053f41e72aa36bfa6b7f55e3529ffa43161b97fa",
  );

  assert.equal(lock.git.length, 2);
  const pest = lock.git.find((p) => p.name === "pest")!;
  assert.equal(pest.url, "https://github.com/pest-parser/pest?branch=master");
  assert.equal(pest.rev, "abc123def456");
});

test("cargo-lock: canonicalGitUrl strips git+ and fragment, keeps query", () => {
  assert.deepEqual(canonicalGitUrl("git+https://github.com/a/b?branch=x#rev1"), {
    url: "https://github.com/a/b?branch=x",
    rev: "rev1",
  });
  assert.deepEqual(canonicalGitUrl("git+https://github.com/a/b.git#deadbeef"), {
    url: "https://github.com/a/b.git",
    rev: "deadbeef",
  });
});

test("cargo-lock: legacy [metadata] checksum table", () => {
  const legacy = `
[[package]]
name = "foo"
version = "0.1.0"
source = "registry+https://github.com/rust-lang/crates.io-index"

[metadata]
"checksum foo 0.1.0 (registry+https://github.com/rust-lang/crates.io-index)" = "aaaa"
`;
  const lock = parseCargoLock(legacy);
  assert.equal(lock.registry.length, 1);
  assert.equal(lock.registry[0]!.checksum, "aaaa");
});

test("paths: object keys mirror the on-disk cache paths", () => {
  // Crate key mirrors registry/cache/<index>/<name>-<ver>.crate exactly.
  assert.equal(
    crateObjectKey("index.crates.io-1949cf8c6b5b557f", "indexmap-2.14.0.crate"),
    "crates/index.crates.io-1949cf8c6b5b557f/indexmap-2.14.0.crate",
  );

  // Git tar key mirrors the git/db/<ident>-<hash> directory name.
  assert.equal(gitDbTarKey("aws-sdk-rust-a7aa3a1434ca033c"), "git-db/aws-sdk-rust-a7aa3a1434ca033c.tar");

  // Sparse-index entry keys use cargo's name sharding (1/2/3/4+ chars).
  const IDX = "index.crates.io-1949cf8c6b5b557f";
  assert.equal(indexEntryObjectKey(IDX, "a"), `registry-index/${IDX}/1/a`);
  assert.equal(indexEntryObjectKey(IDX, "h2"), `registry-index/${IDX}/2/h2`);
  assert.equal(indexEntryObjectKey(IDX, "abc"), `registry-index/${IDX}/3/a/abc`);
  assert.equal(indexEntryObjectKey(IDX, "Serde"), `registry-index/${IDX}/se/rd/serde`); // lowercased
  // Disk path mirrors the key under registry/index/<index>/.cache.
  assert.equal(
    indexEntryDiskPath("/h/.cargo", IDX, "tokio"),
    `/h/.cargo/registry/index/${IDX}/.cache/to/ki/tokio`,
  );

  // Restore discovers it by listing the ident prefix.
  assert.equal(
    gitDbListPrefix("git+https://github.com/boundaryml/aws-sdk-rust.git?rev=abc"),
    "git-db/aws-sdk-rust-",
  );

  assert.equal(gitIdent("https://github.com/pest-parser/pest?branch=master"), "pest");
  assert.equal(gitIdent("https://github.com/example/weird.git"), "weird");
});
